// Literal producer-shaped fixtures, not outputs generated by importer helpers.
const indexJSON = ` {
 "cmake":{"generator":{"name":"Ninja Multi-Config","multiConfig":true}},
 "objects":[{"kind":"codemodel","version":{"major":2,"minor":8},"jsonFile":"model.json"}],
 "reply":{"client-insight":{"query.json":{"requests":[{"kind":"codemodel","version":2}],
 "responses":[{"kind":"codemodel","version":{"major":2,"minor":8},"jsonFile":"model.json"}],
 "client":{"jsonFile":"opaque-not-a-reference"}}}}
} `
const modelJSON = `{
 "kind":"codemodel","version":{"major":2,"minor":8},
 "paths":{"source":"/foreign/src","build":"C:/outside/build"},
 "configurations":[
 {"name":"Debug","directories":[{"source":".","build":".","projectIndex":0,"targetIndexes":[0],"jsonFile":"dir.json"}],
 "projects":[{"name":"Engine","directoryIndexes":[0],"targetIndexes":[0]}],
 "targets":[{"name":"app","id":"app::opaque","directoryIndex":0,"projectIndex":0,"jsonFile":"debug.json"}]},
 {"name":"Release","directories":[{"source":".","build":".","projectIndex":0,"targetIndexes":[0],"jsonFile":"dir.json"}],
 "projects":[{"name":"Engine","directoryIndexes":[0],"targetIndexes":[0]}],
 "targets":[{"name":"app","id":"app::opaque","directoryIndex":0,"projectIndex":0,"jsonFile":"release.json"}]}
 ],"future":{"current":true,"coverage":"complete"}
}`
const debugJSON = `{
 "name":"app","id":"app::opaque","type":"EXECUTABLE","paths":{"source":".","build":"."},
 "sources":[{"path":"src/雪.cc","compileGroupIndex":0,"sourceGroupIndex":0,"backtrace":0},
 {"path":"generated.cc","compileGroupIndex":0,"isGenerated":true},{"path":"/outside/header.h"}],
 "sourceGroups":[{"name":"Sources","sourceIndexes":[0]}],
 "compileGroups":[{"language":"CXX","sourceIndexes":[0,1],
 "compileCommandFragments":[{"fragment":"-DNAME='hello world' @/outside/flags && never-execute","backtrace":0}],
 "defines":[{"define":"A=space value","backtrace":0}],"includes":[{"path":"../inc dir","isSystem":true,"backtrace":0}]}],
 "backtraceGraph":{"commands":["target_sources"],"files":["CMakeLists.txt"],"nodes":[{"file":0,"command":0,"line":4}]},
 "future":{"arguments":["fake","not-observed"],"inferred":true}
}`
const releaseJSON = `{
 "name":"app","id":"app::opaque","type":"EXECUTABLE","paths":{"source":".","build":"."},
 "sources":[{"path":"src/雪.cc","compileGroupIndex":0,"isGenerated":false}],
 "compileGroups":[{"language":"CXX","sourceIndexes":[0],"compileCommandFragments":[{"fragment":"-O3"}]}]
}`
const dirJSON = `{"paths":{"source":".","build":"."},"installers":[]}`

func fixtures() map[string]string {
	return map[string]string{"index.json": indexJSON, "model.json": modelJSON, "debug.json": debugJSON, "release.json": releaseJSON, "dir.json": dirJSON}
}
func inputs(f map[string]string) []cmake.Artifact {
	var out []cmake.Artifact
	for _, name := range []string{"index.json", "model.json", "debug.json", "release.json", "dir.json"} {
		if raw, ok := f[name]; ok {
			out = append(out, cmake.Artifact{Name: name, Provenance: "caller/source-lease-7", Reader: strings.NewReader(raw)})
		}
	}
	return out
}
func importOK(t testing.TB, f map[string]string) cmake.Observation {
	t.Helper()
	o, err := cmake.Import(context.Background(), "index.json", inputs(f), cmake.Limits{})
	if err != nil {
		t.Fatal(err)
	}
	return o
}
func requireFailure(t testing.TB, o cmake.Observation, err, want error) {
	t.Helper()
	if !errors.Is(err, want) {
		t.Fatalf("error = %v, want %v", err, want)
	}
	if !reflect.DeepEqual(o.Snapshot(), cmake.Model{}) || len(o.Identities()) != 0 {
		t.Fatal("partial evidence escaped failure")
	}
	if _, ok := o.Artifact("index.json"); ok {
		t.Fatal("partial artifact escaped failure")
	}
}

func TestLiteralConfigurationsBindingsAndNonclaims(t *testing.T) {
	o := importOK(t, fixtures())
	m := o.Snapshot()
	if m.Version != (cmake.Version{Major: 2, Minor: 8}) || m.Index != "index.json" || m.Codemodel != "model.json" ||
		m.Paths.Source != "/foreign/src" || m.Paths.Build != "C:/outside/build" || len(m.Configurations) != 2 {
		t.Fatalf("model: %+v", m)
	}
	a, b := m.Configurations[0], m.Configurations[1]
	if a.Name != "Debug" || b.Name != "Release" || a.Modules[0].Name != "Engine" ||
		a.Targets[0].ID != "app::opaque" || a.Targets[0].JSONFile != "debug.json" ||
		b.Targets[0].JSONFile != "release.json" || a.Directories[0].JSONFile != "dir.json" {
		t.Fatal("lost configuration/module/reference identity")
	}
	target := a.Targets[0]
	if target.Sources[0].Path != "src/雪.cc" || *target.Sources[0].CompileGroupIndex != 0 ||
		target.Sources[0].IsGenerated != nil || !*target.Sources[1].IsGenerated ||
		target.Sources[2].CompileGroupIndex != nil || *b.Targets[0].Sources[0].IsGenerated {
		t.Fatal("source binding/presence changed or guessed")
	}
	g := target.CompileGroups[0]
	if g.Language != "CXX" || !reflect.DeepEqual(g.SourceIndexes, []int{0, 1}) ||
		g.Fragments[0].Fragment != "-DNAME='hello world' @/outside/flags && never-execute" ||
		g.Defines[0].Define != "A=space value" || g.Includes[0].Path != "../inc dir" ||
		!*g.Includes[0].IsSystem || *g.Fragments[0].Backtrace != 0 ||
		b.Targets[0].CompileGroups[0].Fragments[0].Fragment != "-O3" {
		t.Fatalf("opaque compile observation: %+v", g)
	}
	// Extension assertions remain only raw inert data, never model claims.
	raw, _ := o.Artifact("debug.json")
	if string(raw) != debugJSON || !bytes.Contains(raw, []byte(`"inferred":true`)) {
		t.Fatal("unknown fields not retained exactly")
	}
}

func TestArtifactIdentityReaderChunksAndIsolation(t *testing.T) {
	f := fixtures()
	for _, wrap := range []func(io.Reader) io.Reader{iotest.OneByteReader, iotest.HalfReader, iotest.DataErrReader} {
		in := inputs(f)
		for i := range in {
			in[i].Reader = wrap(in[i].Reader)
		}
		o, err := cmake.Import(context.Background(), "index.json", in, cmake.Limits{})
		if err != nil {
			t.Fatal(err)
		}
		for _, id := range o.Identities() {
			want := f[id.Name]
			if id.Artifact.SHA256 != sha256.Sum256([]byte(want)) || id.Artifact.ObservedBytes != int64(len(want)) ||
				id.Artifact.ImporterVersion != cmake.ImporterVersion || id.Artifact.Format != "cmake-file-api-v1-json" ||
				id.Provenance != "caller/source-lease-7" {
				t.Fatalf("identity %+v", id)
			}
		}
	}
	raw := []byte(debugJSON)
	in := inputs(f)
	in[2].Reader = bytes.NewReader(raw)
	o, err := cmake.Import(context.Background(), "index.json", in, cmake.Limits{})
	if err != nil {
		t.Fatal(err)
	}
	want := o.Snapshot()
	raw[0], in[2].Name = '!', "mutated"
	var wg sync.WaitGroup
	for range 8 {
		wg.Go(func() {
			for range 20 {
				s := o.Snapshot()
				g := &s.Configurations[0].Targets[0].CompileGroups[0]
				g.SourceIndexes[0], g.Defines[0].Define, *g.Includes[0].IsSystem, *g.Fragments[0].Backtrace = 99, "changed", false, 99
				*s.Configurations[0].Targets[0].Sources[0].CompileGroupIndex = 99
				s.Configurations[0].Modules[0].TargetIndexes[0] = 99
				s.Configurations[0].Directories[0].TargetIndexes[0] = 99
				s.Configurations[0].Targets[0].SourceGroups[0].SourceIndexes[0] = 99
				r, _ := o.Artifact("debug.json")
				r[0] = '!'
				ids := o.Identities()
				ids[0].Name = "changed"
				if !reflect.DeepEqual(o.Snapshot(), want) {
					t.Error("mutable export aliases private data")
				}
			}
		})
	}
	wg.Wait()
}

func TestReferenceAndShapeFailuresAreAtomic(t *testing.T) {
	cases := []struct {
		name, file, old, replacement string
		want                         error
	}{
		{"missing target", "model.json", "debug.json", "missing.json", cmake.ErrIncomplete},
		{"unsafe target", "model.json", "debug.json", "../debug.json", cmake.ErrInvalid},
		{"unsafe index ref", "index.json", "model.json", "C:/model.json", cmake.ErrInvalid},
		{"foreign target", "debug.json", `"id":"app::opaque"`, `"id":"foreign"`, cmake.ErrInvalid},
		{"foreign object", "model.json", `"kind":"codemodel"`, `"kind":"cache"`, cmake.ErrInvalid},
		{"duplicate reference", "model.json", `"targets":[{`, `"targets":[{"name":"app","id":"app::opaque","directoryIndex":0,"projectIndex":0,"jsonFile":"debug.json"},{`, cmake.ErrInvalid},
		{"duplicate config", "model.json", `"name":"Release"`, `"name":"Debug"`, cmake.ErrInvalid},
		{"major", "index.json", `"major":2`, `"major":3`, cmake.ErrInvalid},
		{"negative index", "debug.json", `"compileGroupIndex":0`, `"compileGroupIndex":-1`, cmake.ErrInvalid},
		{"foreign source index", "debug.json", `"sourceIndexes":[0,1]`, `"sourceIndexes":[0,99]`, cmake.ErrInvalid},
		{"duplicate source index", "debug.json", `"sourceIndexes":[0,1]`, `"sourceIndexes":[0,0]`, cmake.ErrInvalid},
		{"missing source reverse binding", "debug.json", `"sourceIndexes":[0,1]`, `"sourceIndexes":[0]`, cmake.ErrInvalid},
		{"module index", "model.json", `"projectIndex":0`, `"projectIndex":9`, cmake.ErrInvalid},
		{"directory tree self cycle", "model.json", `"projectIndex":0`, `"parentIndex":0,"childIndexes":[0],"projectIndex":0`, cmake.ErrInvalid},
		{"missing directory", "model.json", "dir.json", "missing.json", cmake.ErrIncomplete},
		{"foreign directory", "dir.json", `"source":"."`, `"source":"foreign"`, cmake.ErrInvalid},
		{"dependency", "debug.json", `"type":"EXECUTABLE"`, `"dependencies":[{"id":"foreign"}],"type":"EXECUTABLE"`, cmake.ErrInvalid},
		{"null flag", "debug.json", `"isGenerated":true`, `"isGenerated":null`, cmake.ErrInvalid},
		{"bad backtrace", "debug.json", `"backtrace":0`, `"backtrace":99`, cmake.ErrInvalid},
		{"unmatched reply", "index.json", `"client-insight"`, `"future":{"kind":"cache","version":{"major":2,"minor":0},"jsonFile":"dir.json"},"client-insight"`, cmake.ErrInvalid},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f := fixtures()
			f[c.file] = strings.Replace(f[c.file], c.old, c.replacement, 1)
			o, err := cmake.Import(context.Background(), "index.json", inputs(f), cmake.Limits{})
			requireFailure(t, o, err, c.want)
		})
	}
	f := fixtures()
	f["index.json"], f["model.json"] = strings.ReplaceAll(indexJSON, `"major":2`, `"major":3`), strings.ReplaceAll(modelJSON, `"major":2`, `"major":3`)
	o, err := cmake.Import(context.Background(), "index.json", inputs(f), cmake.Limits{})
	requireFailure(t, o, err, cmake.ErrUnsupported)
	in := inputs(fixtures())
	in = append(in, in[0])
	o, err = cmake.Import(context.Background(), "index.json", in, cmake.Limits{})
	requireFailure(t, o, err, cmake.ErrInvalid)
}

func TestStrictJSONAndLimits(t *testing.T) {
	for _, bad := range []string{
		`{"x":1,"\u0078":2}`, `{"x":{"a":1,"a":1}}`, `{"x":"\ud800"}`, `{"x":"\udfff"}`,
		`{"x":"\ud800\u0041"}`, `{"x":"\u00xx"}`, "{\"x\":\"\xff\"}", `{"x":[1,]}`, `{"x":01}`,
		`{"x":true} {}`, `{"x":true`, "",
	} {
		f := fixtures()
		// Put malformed data in an extension of an otherwise valid directory,
		// so last-wins/replacement-decoding would wrongly succeed.
		f["dir.json"] = strings.TrimSuffix(dirJSON, "}") + `,"extension":` + bad + `}`
		o, err := cmake.Import(context.Background(), "index.json", inputs(f), cmake.Limits{})
		requireFailure(t, o, err, cmake.ErrInvalid)
	}
	f := fixtures()
	f["dir.json"] = strings.TrimSuffix(dirJSON, "}") + `,"unicode":"\ud83d\ude00","extensions":[null,true,false,-1,1e5]}`
	importOK(t, f)
	for i := range len(debugJSON) {
		f := fixtures()
		f["debug.json"] = debugJSON[:i]
		o, err := cmake.Import(context.Background(), "index.json", inputs(f), cmake.Limits{})
		requireFailure(t, o, err, cmake.ErrInvalid)
	}
	for _, l := range []cmake.Limits{
		{MaxTotalBytes: len(indexJSON)}, {MaxArtifactBytes: len(indexJSON) - 1}, {MaxArtifacts: 4},
		{MaxValues: 20}, {MaxDepth: 2}, {MaxItems: 2}, {MaxStringBytes: 20},
	} {
		o, err := cmake.Import(context.Background(), "index.json", inputs(fixtures()), l)
		requireFailure(t, o, err, cmake.ErrLimit)
	}
	for _, l := range []cmake.Limits{{MaxDepth: -1}, {MaxArtifacts: 129}} {
		o, err := cmake.Import(context.Background(), "index.json", inputs(fixtures()), l)
		requireFailure(t, o, err, cmake.ErrInvalid)
	}
	total, largest := 0, 0
	for _, text := range fixtures() {
		total += len(text)
		largest = max(largest, len(text))
	}
	if _, err := cmake.Import(context.Background(), "index.json", inputs(fixtures()), cmake.Limits{MaxTotalBytes: total, MaxArtifactBytes: largest}); err != nil {
		t.Fatalf("exact bound: %v", err)
	}
}

type readerFunc func([]byte) (int, error)

func (f readerFunc) Read(p []byte) (int, error) { return f(p) }

func TestReaderErrorsAndCancellation(t *testing.T) {
	boom := errors.New("reader failed")
	for _, r := range []io.Reader{
		iotest.ErrReader(boom), io.MultiReader(strings.NewReader(dirJSON), iotest.ErrReader(boom)),
		readerFunc(func(p []byte) (int, error) { return copy(p, dirJSON), boom }),
	} {
		in := inputs(fixtures())
		in[4].Reader = r
		o, err := cmake.Import(context.Background(), "index.json", in, cmake.Limits{})
		requireFailure(t, o, err, boom)
	}
	for _, r := range []io.Reader{
		readerFunc(func(p []byte) (int, error) { return len(p) + 1, nil }),
		readerFunc(func(_ []byte) (int, error) { return -1, nil }),
	} {
		in := inputs(fixtures())
		in[4].Reader = r
		o, err := cmake.Import(context.Background(), "index.json", in, cmake.Limits{})
		requireFailure(t, o, err, cmake.ErrInvalid)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	o, err := cmake.Import(ctx, "index.json", inputs(fixtures()), cmake.Limits{})
	requireFailure(t, o, err, context.Canceled)
	ctx, cancel = context.WithCancel(context.Background())
	in := inputs(fixtures())
	in[4].Reader = readerFunc(func(p []byte) (int, error) { cancel(); return copy(p, dirJSON), io.EOF })
	o, err = cmake.Import(ctx, "index.json", in, cmake.Limits{})
	requireFailure(t, o, err, context.Canceled)
}

func TestNestedModulesAndObservedDependency(t *testing.T) {
	f := fixtures()
	f["index.json"] = strings.ReplaceAll(indexJSON, `"minor":8`, `"minor":0`)
	f["model.json"] = `{"kind":"codemodel","version":{"major":2,"minor":0},
	"paths":{"source":"/s","build":"/b"},"configurations":[{"name":"",
	"directories":[{"source":".","build":".","projectIndex":0,"childIndexes":[1],"targetIndexes":[0]},
	{"source":"sub","build":"sub","projectIndex":1,"parentIndex":0,"targetIndexes":[1]}],
	"projects":[{"name":"Root","directoryIndexes":[0],"targetIndexes":[0],"childIndexes":[1]},
	{"name":"Nested","directoryIndexes":[1],"targetIndexes":[1],"parentIndex":0}],
	"targets":[{"name":"app","id":"app::opaque","directoryIndex":0,"projectIndex":0,"jsonFile":"debug.json"},
	{"name":"lib","id":"lib::opaque","directoryIndex":1,"projectIndex":1,"jsonFile":"release.json"}]}]}`
	f["debug.json"] = strings.Replace(debugJSON, `"type":"EXECUTABLE"`, `"type":"EXECUTABLE","dependencies":[{"id":"lib::opaque"}]`, 1)
	f["release.json"] = `{"name":"lib","id":"lib::opaque","type":"STATIC_LIBRARY","paths":{"source":"sub","build":"sub"},"sources":[]}`
	o := importOK(t, f)
	m := o.Snapshot().Configurations[0]
	if m.Name != "" || m.Modules[1].Name != "Nested" || *m.Modules[1].ParentIndex != 0 ||
		m.Targets[1].ProjectIndex != 1 || m.Targets[0].Dependencies[0] != "lib::opaque" {
		t.Fatal("nested identity or dependency changed")
	}
	*m.Modules[1].ParentIndex = 99
	m.Targets[0].Dependencies[0] = "mutated"
	if *o.Snapshot().Configurations[0].Modules[1].ParentIndex != 0 ||
		o.Snapshot().Configurations[0].Targets[0].Dependencies[0] != "lib::opaque" {
		t.Fatal("nested export aliases observation")
	}
}
